nta.declaration:
// Cloud-only energy consumption model
		const int N=2;
		typedef int[0, N-1] id_t;
		
		// Cloud computing parameters
		const int cloudInstructions=600;
		
		// Energy consumption parameters (units: millijoules)
		const int cloudEnergyPerInstruction = 5;    // mJ per instruction
		const int cloudEnergyPerMemoryUnit = 1;     // mJ per memory unit
		const int cloudEnergyPerDataUnit = 1;       // mJ per communication data unit
		
		// Communication channels
		chan execute[N], completed[N], parallel[N];
		
		// Energy tracking variables
		int totalEnergyConsumed = 0;
		int finalEnergyConsumption = 0;
		int executionTime = 0;
		
		// Fragment tracking
		int currentFragment;
		bool fragmentsCompleted[N];
		int fragmentsExecuted = 0;
		
		// Fragment information structure
		typedef struct {
			int instructions;           // Number of instructions to execute
			int memory;                // Memory requirements
			int communicationData;     // Data transfer requirements
		} FragmentInfo;
		
		const FragmentInfo Info[N] = {
			{35, 8, 3}
			,
			{15, 5, 2}
		};
		
		
		
		// Helper functions
		void prepareExecution(int fragmentId) {
			// Initialize fragment for execution
			fragmentsCompleted[fragmentId] = false;
		}

template.declaration:
void executeFragment(int fragmentId) {
	// Calculate energy consumption based on fragment characteristics
	int computationEnergy = Info[fragmentId].instructions * cloudEnergyPerInstruction;
	int memoryEnergy = Info[fragmentId].memory * cloudEnergyPerMemoryUnit;
	int communicationEnergy = Info[fragmentId].communicationData * cloudEnergyPerDataUnit;
	
	// Update total energy consumption
	totalEnergyConsumed += computationEnergy + memoryEnergy + communicationEnergy;
	
	// Update execution time
	executionTime += ((Info[fragmentId].instructions * 10) / cloudInstructions);
	if(executionTime == 0) executionTime = 1; // Minimum execution time
	
	// Mark fragment as completed
	fragmentsCompleted[fragmentId] = true;
}

// Energy monitoring functions
bool allFragmentsCompleted() {
	int i;
	for(i = 0; i < N; i++) {
		if(!fragmentsCompleted[i]) return false;
	}
	return true;
}

int calculateTotalEnergy() {
	return totalEnergyConsumed;
}

int calculateAverageEnergyPerFragment() {
	if(N > 0) return totalEnergyConsumed / N;
	return 0;
}
